package com.bank.stores.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class LedgerTransferService {   // MySQL — ACID + foreign keys guard the money
    private static final Logger log = LoggerFactory.getLogger(LedgerTransferService.class);
    private final JdbcTemplate jdbc;

    public LedgerTransferService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    @Transactional   // debit + credit + record commit together or roll back
    public void transfer(String fromId, String toId, BigDecimal amount) {
        jdbc.update("UPDATE accounts SET balance = balance - ? WHERE account_id = ?", amount, fromId);
        jdbc.update("UPDATE accounts SET balance = balance + ? WHERE account_id = ?", amount, toId);
        jdbc.update("INSERT INTO transfers (from_id, to_id, amount) VALUES (?,?,?)", fromId, toId, amount);
        log.info("MySQL ACID transfer {} {}->{}", amount, fromId, toId);
    }
}
