package com.bank.stores.model;

import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;
import java.util.List;
import java.util.Map;

@Document(collection = "profiles")   // flexible schema — fields can vary per customer
public class CustomerProfile {
    @Id
    private String accountId;
    private String name;
    private Map<String, Object> prefs;              // nested, evolves without migration
    private List<Map<String, Object>> notifications; // embedded array — no join needed

    public CustomerProfile() {}
    public CustomerProfile(String accountId, String name,
                           Map<String, Object> prefs, List<Map<String, Object>> notifications) {
        this.accountId = accountId; this.name = name;
        this.prefs = prefs; this.notifications = notifications;
    }
    public String getAccountId() { return accountId; }
}
