package com.bank.stores.service;

import com.bank.stores.model.CustomerProfile;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.stereotype.Service;

@Service
public class CustomerProfileService {   // MongoDB — flexible, one read returns everything
    private static final Logger log = LoggerFactory.getLogger(CustomerProfileService.class);
    private final MongoTemplate mongo;

    public CustomerProfileService(MongoTemplate mongo) { this.mongo = mongo; }

    // Save the whole profile as one document; adding a new pref needs NO migration.
    public void save(CustomerProfile profile) {
        mongo.save(profile);
        log.info("MongoDB saved flexible profile for {} (embedded, no joins)", profile.getAccountId());
    }

    // One lookup by _id returns the profile with all nested prefs and notifications.
    public CustomerProfile get(String accountId) {
        CustomerProfile p = mongo.findById(accountId, CustomerProfile.class);
        log.info("MongoDB read profile {} in a single document read", accountId);
        return p;
    }
}
