package com.bank.stores.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class StoreSelector {
    private static final Logger log = LoggerFactory.getLogger(StoreSelector.class);

    // Recommend MySQL or MongoDB from the workload's needs.
    public String choose(boolean relationalAcidMoney, boolean flexibleReadHeavyAtScale) {
        if (relationalAcidMoney) {
            log.info("Relational + ACID money → MySQL (joins, constraints, transactions)");
            return "MySQL";
        }
        if (flexibleReadHeavyAtScale) {
            log.info("Flexible schema + read-heavy + horizontal scale → MongoDB");
            return "MongoDB";
        }
        log.info("Default to MySQL for safe, consistent, queryable storage");
        return "MySQL";
    }
}
